    49→/// Record the latest SUT metrics snapshot as OTel gauge values.
    50→fn record_sut_metrics(response: &MetricsResponse, attributes: &[KeyValue]) {
    51→    // Resource metrics
    52→    if let Some(cpu) = response.resource.cpu_usage_percent {
    53→        crate::metrics::SUT_CPU_USAGE_PERCENT.record(cpu, attributes);
    54→    }
    55→    if let Some(mem) = response.resource.memory_usage_bytes {
    56→        crate::metrics::SUT_MEMORY_USAGE_BYTES.record(mem, attributes);
    57→    }
    58→    if let Some(v) = response.resource.disk_read_bytes {
    59→        crate::metrics::SUT_DISK_READ_BYTES.record(v, attributes);
    60→    }
    61→    if let Some(v) = response.resource.disk_write_bytes {
    62→        crate::metrics::SUT_DISK_WRITE_BYTES.record(v, attributes);
    63→    }
    64→    if let Some(v) = response.resource.disk_read_iops {
    65→        crate::metrics::SUT_DISK_READ_IOPS.record(v, attributes);
    66→    }
    67→    if let Some(v) = response.resource.disk_write_iops {
    68→        crate::metrics::SUT_DISK_WRITE_IOPS.record(v, attributes);
    69→    }
    70→
    71→    // Ingestion metrics
    72→    if let Some(v) = response.ingestion.rows_ingested {
    73→        crate::metrics::INGESTION_ROWS_TOTAL.record(v, attributes);
    74→    }
    75→    if let Some(v) = response.ingestion.bytes_ingested {
    76→        crate::metrics::INGESTION_BYTES_TOTAL.record(v, attributes);
    77→    }
    78→    if let Some(v) = response.ingestion.rows_per_sec {
    79→        crate::metrics::INGESTION_ROWS_PER_SEC.record(v, attributes);
    80→    }
    81→    if let Some(v) = response.ingestion.active_connections {
    82→        crate::metrics::ACTIVE_CONNECTIONS.record(v, attributes);
    83→    }
    84→}
    85→
    86→/// Spawn a task that periodically scrapes SUT metrics from the system adapter.
    87→///
    88→/// Returns a `JoinHandle` that resolves to the last `MetricsResponse` received
    89→/// (or `None` if no successful scrape occurred).
    90→fn spawn_sut_metrics_scraper(
    91→    adapter: Arc<Mutex<system_adapter_protocol::Client>>,
    92→    run_id: uuid::Uuid,
    93→    token: CancellationToken,
    94→    interval: Duration,
    95→    attributes: Vec<KeyValue>,
    96→) -> tokio::task::JoinHandle<Option<MetricsResponse>> {
    97→    tokio::spawn(async move {
    98→        let mut last_response: Option<MetricsResponse> = None;
    99→        let mut ticker = tokio::time::interval(interval);
   100→        loop {
   101→            tokio::select! {
   102→                _ = ticker.tick() => {
   103→                    let metrics_result = adapter.lock().await.metrics(run_id).await;
   104→                    match metrics_result {
   105→                        Ok(resp) => {
   106→                            let cpu_pct = resp
   107→                                .resource
   108→                                .cpu_usage_percent
   109→                                .map(|v| format!("{v:.2}%"))
   110→                                .unwrap_or_else(|| "n/a".to_string());
   111→                            let mem_mb = resp
   112→                                .resource
   113→                                .memory_usage_bytes
   114→                                .map(|v| format!("{:.2}", v as f64 / (1024.0 * 1024.0)))
   115→                                .unwrap_or_else(|| "n/a".to_string());
   116→                            let rows_per_sec = resp
   117→                                .ingestion
   118→                                .rows_per_sec
   119→                                .map(|v| format!("{v:.2}"))
   120→                                .unwrap_or_else(|| "n/a".to_string());
   121→                            let active_connections = resp
   122→                                .ingestion
   123→                                .active_connections
   124→                                .map(|v| v.to_string())
   125→                                .unwrap_or_else(|| "n/a".to_string());
   126→
   127→                            println!(
   128→                                "SUT metrics: cpu={} mem_mb={} rows_per_sec={} active_connections={}",
   129→                                cpu_pct, mem_mb, rows_per_sec, active_connections
   130→                            );
   131→                            record_sut_metrics(&resp, &attributes);
   132→                            last_response = Some(resp);
   133→                        }
   134→                        Err(e) => {
   135→                            eprintln!("SUT metrics scrape failed: {e}");
   136→                        }
   137→                    }
   138→                }
   139→                () = token.cancelled() => {
   140→                    // Final scrape before exiting
   141→                    if let Ok(resp) = adapter.lock().await.metrics(run_id).await {
   142→                        record_sut_metrics(&resp, &attributes);
   143→                        last_response = Some(resp);
   144→                    }
   145→                    break;
   146→                }
   147→            }
   148→        }
   149→        last_response
   150→    })
   151→}
   152→
   153→/// Spawn a task that periodically queries `SELECT MAX(__created_at)` for each
   154→/// table and records the freshness delay (`now − max_created_at`).
   155→///
   156→/// Returns a map of table name → vec of freshness samples (in milliseconds).
   157→fn spawn_e2e_latency_check(
   158→    pool: adbc_client::AdbcConnectionPool,
   159→    table_names: Vec<String>,
   160→    query_catalog_namespace: Option<String>,
   161→    token: CancellationToken,
   162→    interval: Duration,
   163→    last_created_at_us: Arc<HashMap<String, AtomicI64>>,
   164→) -> tokio::task::JoinHandle<HashMap<String, Vec<f64>>> {
   165→    tokio::spawn(async move {
   166→        println!(
   167→            "E2E latency checker started (interval={}s)",
   168→            interval.as_secs()
   169→        );
   170→        let mut samples_by_table: HashMap<String, Vec<f64>> = table_names
   171→            .iter()
   172→            .map(|t| (t.clone(), Vec::new()))
   173→            .collect();
   174→        let mut ticker = tokio::time::interval(interval);
   175→        loop {
   176→            tokio::select! {
   177→                _ = ticker.tick() => {}
   178→                () = token.cancelled() => break,
   179→            }
   180→
   181→            let pool = pool.clone();
   182→            let tables = table_names.clone();
   183→            let timestamps = Arc::clone(&last_created_at_us);
   184→            let query_catalog_namespace = query_catalog_namespace.clone();
   185→            let results = tokio::task::spawn_blocking(move || {
   186→                let mut out: Vec<(String, Option<f64>)> = Vec::new();
   187→                let mut conn = match pool.get() {
   188→                    Ok(c) => c,
   189→                    Err(e) => {
   190→                        eprintln!("E2E latency checker: failed to get connection: {e}");
   191→                        return out;
   192→                    }
   193→                };
   194→                for table in &tables {
   195→                    let last_written_us = timestamps
   196→                        .get(table.as_str())
   197→                        .map_or(0, |a| a.load(Ordering::Relaxed));
   198→                    if last_written_us == 0 {
   199→                        out.push((table.clone(), None));
   200→                        continue;
   201→                    }
   202→                    let table_ref = if let Some(namespace) = query_catalog_namespace
   203→                        .as_deref()
   204→                        .map(str::trim)
   205→                        .filter(|ns| !ns.is_empty())
   206→                    {
   207→                        if table.contains('.') {
   208→                            table.to_string()
   209→                        } else {
   210→                            format!("{namespace}.{table}")
   211→                        }
   212→                    } else {
   213→                        table.to_string()
   214→                    };
   215→
   216→                    let sql = format!("SELECT MAX(__created_at) FROM {table_ref}");
   217→                    match conn.query(&sql) {
   218→                        Ok(batches) => {
   219→                            let sample = batches.first().and_then(|batch| {
   220→                                let col = batch.column(0);
   221→                                let ts_array =
   222→                                    col.as_any().downcast_ref::<TimestampMicrosecondArray>()?;
   223→                                if ts_array.is_null(0) {
   224→                                    return None;
   225→                                }
   226→                                let max_ts_us = ts_array.value(0);
   227→                                Some((last_written_us - max_ts_us) as f64 / 1000.0)
   228→                            });
   229→                            out.push((table.clone(), sample));
   230→                        }
   231→                        Err(e) => {
   232→                            eprintln!("E2E latency checker: query failed for {table}: {e}");
   233→                            out.push((table.clone(), None));
   234→                        }
   235→                    }
   236→                }
   237→                out
   238→            })
   239→            .await;
   240→
   241→            if let Ok(results) = results {
   242→                let mut sampled_count = 0usize;
   243→                let mut missing_count = 0usize;
   244→                let mut min_ms = f64::INFINITY;
   245→                let mut max_ms = f64::NEG_INFINITY;
   246→                let mut sum_ms = 0.0;
   247→
   248→                for (table, sample) in results {
   249→                    if let Some(ms) = sample {
   250→                        samples_by_table.entry(table).or_default().push(ms);
   251→                        sampled_count += 1;
   252→                        sum_ms += ms;
   253→                        min_ms = min_ms.min(ms);
   254→                        max_ms = max_ms.max(ms);
   255→                    } else {
   256→                        missing_count += 1;
   257→                    }
   258→                }
   259→
   260→                if sampled_count > 0 {
   261→                    println!(
   262→                        "E2E latency checker: tables={} sampled={} missing={} min_ms={:.2} avg_ms={:.2} max_ms={:.2}",
   263→                        sampled_count + missing_count,
   264→                        sampled_count,
   265→                        missing_count,
   266→                        min_ms,
   267→                        sum_ms / sampled_count as f64,
   268→                        max_ms
   269→                    );
   270→                } else {
   271→                    println!(
   272→                        "E2E latency checker: tables={} sampled=0 missing={}",
   273→                        missing_count, missing_count
   274→                    );
   275→                }
   276→            }
   277→        }
   278→        samples_by_table
   279→    })
   280→}
   281→
   282→/// Load checkpoint expected results from parquet files on disk for a given
   283→/// checkpoint index.
   284→///
   285→/// The checkpoints directory is laid out as:
   286→/// ```text
   287→/// {checkpoint_dir}/{checkpoint_idx}/{query_idx}.parquet
   288→/// ```
   289→///
   290→/// `query_names` provides the ordered mapping from `query_idx` to the query
   291→/// name used as keys in the returned map.
   292→///
   293→/// Returns a map of query name → expected `RecordBatch`es. Queries for which
   294→/// the parquet file does not exist are silently skipped.
   295→fn load_checkpoint_results(
   296→    checkpoint_dir: &Path,
   297→    checkpoint_idx: usize,
   298→    query_names: &[Arc<str>],
   299→) -> anyhow::Result<HashMap<Arc<str>, Vec<RecordBatch>>> {
   300→    use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
   301→
   302→    let idx_dir = checkpoint_dir.join(checkpoint_idx.to_string());
   303→    if !idx_dir.is_dir() {
   304→        anyhow::bail!("Checkpoint directory does not exist: {}", idx_dir.display());
   305→    }
   306→
   307→    let mut results: HashMap<Arc<str>, Vec<RecordBatch>> = HashMap::new();
   308→
   309→    for (query_idx, query_name) in query_names.iter().enumerate() {
   310→        let parquet_path = idx_dir.join(format!("{query_idx}.parquet"));
   311→        if !parquet_path.exists() {
   312→            tracing::debug!(
   313→                checkpoint = checkpoint_idx,
   314→                query = query_idx,
   315→                name = query_name.as_ref(),
   316→                "Checkpoint parquet not found, skipping"
   317→            );
   318→            continue;
   319→        }
   320→
   321→        let file = std::fs::File::open(&parquet_path)?;
   322→        let builder = ParquetRecordBatchReaderBuilder::try_new(file)?;
   323→        let reader = builder.build()?;
   324→        let batches: Vec<RecordBatch> = reader.collect::<Result<_, _>>()?;
   325→
   326→        tracing::debug!(
   327→            checkpoint = checkpoint_idx,
   328→            query = query_idx,
   329→            name = query_name.as_ref(),
   330→            rows = batches.iter().map(|b| b.num_rows()).sum::<usize>(),
   331→            "Loaded checkpoint expected results"
   332→        );
   333→
   334→        results.insert(Arc::clone(query_name), batches);
   335→    }
   336→
   337→    Ok(results)
   338→}
   339→
   340→#[expect(clippy::too_many_lines)]
   341→#[expect(clippy::too_many_arguments)]
   342→pub(crate) async fn run(
   343→    system_adapter_client: Arc<Mutex<system_adapter_protocol::Client>>,
   344→    run_id: uuid::Uuid,
   345→    scenario: &Scenario,
   346→    common_args: &CommonArgs,
   347→    version_metadata: &VersionMetadata,
   348→    read_pool: adbc_client::AdbcConnectionPool,
   349→    etl_pipeline: &mut ETLPipeline,
   350→    checkpoint_steps: Option<usize>,
   351→    checkpoint_dir: Option<&Path>,
   352→    query_catalog_namespace: Option<String>,
   353→) -> anyhow::Result<()> {
   354→    let metric_attributes = run_metric_attributes(common_args);
   355→
   356→    scenario.load_query_set()?;
   357→
   358→    let load_resource = Resource::builder_empty()
   359→        .with_attributes(vec![
   360→            KeyValue::new("service.name", "spicebench"),
   361→            KeyValue::new("type", "spicebench"),
   362→            KeyValue::new("adapter_name", common_args.system_adapter_name.clone()),
   363→            KeyValue::new("scenario", scenario.to_string()),
   364→            KeyValue::new("data_gen_version", common_args.etl_version.clone()),
   365→            KeyValue::new("scale_factor", version_metadata.scale_factor.to_string()),
   366→        ])
   367→        .build();
   368→
   369→    // Create telemetry with resource upfront, before any metrics calls
   370→    let telemetry = super::create_telemetry_with_resource(common_args, load_resource);
   371→
   372→    // Create the appropriate query executor based on args.
   373→    // Each worker gets its own connection from the pool.
   374→    let executor = Box::new(adbc_executor::AdbcDirectQueryExecutor::new(
   375→        read_pool.clone(),
   376→    ));
   377→
   378→    println!("Running benchmark");
   379→
   380→    let load_end_condition = scenario.end_condition();
   381→
   382→    // Create streaming OTLP exporter if OTLP endpoint is configured
   383→    let streaming_exporter = common_args
   384→        .otlp_endpoint
   385→        .as_ref()
   386→        .map(|endpoint| StreamingOtlpExporter::spawn(endpoint.clone()));
   387→
   388→    // Spawn SUT metrics scraper if --scrape-sut-metrics is enabled and a system adapter is configured
   389→    let sut_scraper_token = CancellationToken::new();
   390→    let sut_scraper_handle = if common_args.scrape_sut_metrics
   391→        && (common_args.system_adapter_stdio_cmd.is_some()
   392→            || common_args.system_adapter_http_url.is_some())
   393→    {
   394→        println!("SUT metrics scraping enabled (run_id={run_id})");
   395→        Some(spawn_sut_metrics_scraper(
   396→            system_adapter_client,
   397→            run_id,
   398→            sut_scraper_token.clone(),
   399→            Duration::from_secs(5),
   400→            metric_attributes.clone(),
   401→        ))
   402→    } else {
   403→        None
   404→    };
   405→
   406→    // Record client concurrency as a gauge
   407→    crate::metrics::ACTIVE_CONNECTIONS.record(
   408→        common_args.concurrency.try_into().unwrap_or(0),
   409→        &metric_attributes,
   410→    );
   411→
   412→    let mut test_builder = NotStarted::new()
   413→        .with_parallel_count(common_args.concurrency)
   414→        .with_end_condition(load_end_condition)
   415→        .with_query_executor(executor);
   416→
   417→    // Add streaming metrics sender if exporter is configured
   418→    if let Some(exporter) = &streaming_exporter {
   419→        test_builder = test_builder.with_streaming_metrics(exporter.sender());
   420→    }
   421→
   422→    // Always create validation channels so we can track query-set iteration
   423→    // completions. When --validate-results is enabled with checkpoint data,
   424→    // these channels are also used for checkpoint-based results validation.
   425→    let (validation_controller, validation_worker_handles) = create_validation_channels();
   426→    test_builder = test_builder.with_checkpoint_validation(validation_worker_handles);
   427→
   428→    let has_checkpoint_validation =
   429→        common_args.validate_results && checkpoint_steps.is_some() && checkpoint_dir.is_some();
   430→
   431→    // Spawn e2e checker — only when checkpoint validation is NOT enabled,
   432→    // since checkpoint validation provides its own e2e latency measurement.
   433→    let e2e_latency_token = CancellationToken::new();
   434→    let e2e_latency_handle = if !has_checkpoint_validation {
   435→        let table_names: Vec<String> = etl_pipeline.dataset().tables().keys().cloned().collect();
   436→        Some(spawn_e2e_latency_check(
   437→            read_pool.clone(),
   438→            table_names,
   439→            query_catalog_namespace.clone(),
   440→            e2e_latency_token.clone(),
   441→            Duration::from_secs(5),
   442→            etl_pipeline.last_created_at_us(),
   443→        ))
   444→    } else {
   445→        None
   446→    };
   447→
   448→    let (query_set, test_builder) = super::build_test_with_validation(
   449→        scenario,
   450→        test_builder,
   451→        query_catalog_namespace.as_deref(),
   452→    )
   453→    .await?;
   454→
   455→    // Build ordered query names for mapping checkpoint query_idx → query name.
   456→    let queries = query_set.get_queries(None, None, None).await?;
   457→    let query_names: Vec<Arc<str>> = queries.iter().map(|q| Arc::clone(&q.name)).collect();
   458→
   459→    let throughput_test = SpiceTest::<NotStarted>::new(scenario.to_string(), test_builder)
   460→        .with_progress_bars(false)
   461→        .start()?;
   462→    let shutdown_token = throughput_test.cancellation_token();
   463→
   464→    // --- Start the ETL pipeline (remaining batches) ---
   465→    // If checkpoint_steps is set, use `.run(steps)` so the pipeline pauses
   466→    // at checkpoint boundaries. Otherwise fall back to `.start()` which runs
   467→    // all remaining batches without pausing.
   468→    tracing::info!("Starting ETL pipeline (remaining batches)...");
   469→    let mut etl_state_rx = etl_pipeline.state_watch();
   470→    if let Some(steps) = checkpoint_steps {
   471→        tracing::info!(checkpoint_steps = steps, "Using checkpoint-aware ETL mode");
   472→        etl_pipeline.run(steps).await?;
   473→    } else {
   474→        etl_pipeline.start().await?;
   475→    }
   476→
   477→    let test_future = throughput_test.wait();
   478→    tokio::pin!(test_future);
   479→
   480→    // Wait for ETL pipeline state changes, handling both pauses (checkpoint
   481→    // boundaries) and stops (completion / error / cancellation).
   482→    //
   483→    // When the pipeline pauses at a checkpoint boundary we immediately
   484→    // continue it. TODO: In the future this is where checkpoint-based query result
   485→    // validation would be triggered before resuming.
   486→    //
   487→    // If interrupted (ctrl-c), cancel both the test and the ETL pipeline.
   488→    let etl_error: Option<String> = loop {
   489→        tokio::select! {
   490→            // ETL state changed — check if stopped or paused
   491→            _ = etl_state_rx.changed() => {
   492→                let state = etl_state_rx.borrow_and_update().clone();
   493→                match state {
   494→                    PipelineState::Paused => {
   495→                        let checkpoint_idx = etl_pipeline.checkpoint_idx();
   496→                        tracing::info!(
   497→                            checkpoint_idx,
   498→                            "ETL pipeline paused at checkpoint boundary"
   499→                        );
   500→
   501→                        // --- Checkpoint validation window ---
   502→                        if has_checkpoint_validation
   503→                            && let Some(cp_dir) = checkpoint_dir
   504→                        {
   505→                            match load_checkpoint_results(cp_dir, checkpoint_idx, &query_names) {
   506→                                Ok(expected_results) if !expected_results.is_empty() => {
   507→                                    tracing::info!(
   508→                                        checkpoint_idx,
   509→                                        num_queries = expected_results.len(),
   510→                                        "Enabling checkpoint validation"
   511→                                    );
   512→
   513→                                    let etl_pause_time = tokio::time::Instant::now();
   514→
   515→                                    // Tell worker 0 to start validating.
   516→                                    let _ = validation_controller.command_tx.send(Some(
   517→                                        ValidationCommand::Enable {
   518→                                            checkpoint_idx,
   519→                                            expected_results,
   520→                                        },
   521→                                    ));
   522→
   523→                                    // Poll the validation status until convergence
   524→                                    // (a complete iteration where every query passes)
   525→                                    // or until the timeout is reached.
   526→                                    const POLL_INTERVAL: Duration = Duration::from_secs(5);
   527→                                    const MAX_WAIT: Duration = Duration::from_secs(600);
   528→                                    let mut timed_out = false;
   529→                                    loop {
   530→                                        let status =
   531→                                            validation_controller.status_rx.borrow().clone();
   532→                                        if status.converged() {
   533→                                            let latency_ms =
   534→                                                etl_pause_time.elapsed().as_secs_f64() * 1000.0;
   535→                                            println!(
   536→                                                "Checkpoint {} converged in {:.1}s ({} iterations)",
   537→                                                checkpoint_idx,
   538→                                                latency_ms / 1000.0,
   539→                                                status.completed_iterations(),
   540→                                            );
   541→                                            crate::metrics::E2E_LATENCY_MS
   542→                                                .record(latency_ms, &metric_attributes);
   543→                                            break;
   544→                                        }
   545→                                        if etl_pause_time.elapsed() >= MAX_WAIT {
   546→                                            timed_out = true;
   547→                                            break;
   548→                                        }
   549→                                        tokio::time::sleep(POLL_INTERVAL).await;
   550→                                    }
   551→
   552→                                    // Read the validation status before disabling.
   553→                                    let status = validation_controller.status_rx.borrow().clone();
   554→                                    if let ValidationStatus::Active {
   555→                                        checkpoint_idx: idx,
   556→                                        outcomes,
   557→                                        completed_iterations: iters,
   558→                                        converged,
   559→                                    } = &status
   560→                                    {
   561→                                        let total_pass: usize =
   562→                                            outcomes.iter().map(|o| o.pass_count).sum();
   563→                                        let total_fail: usize =
   564→                                            outcomes.iter().map(|o| o.fail_count).sum();
   565→                                        println!(
   566→                                            "Checkpoint {idx} validation ({iters} iterations, converged={converged}): {} queries, {total_pass} pass, {total_fail} fail",
   567→                                            outcomes.len()
   568→                                        );
   569→                                        if total_fail > 0 {
   570→                                            for o in outcomes {
   571→                                                if o.fail_count > 0 {
   572→                                                    eprintln!(
   573→                                                        "  FAIL - query '{}': {} pass, {} fail, last failure: {:?}",
   574→                                                        o.query_name,
   575→                                                        o.pass_count,
   576→                                                        o.fail_count,
   577→                                                        o.last_failure
   578→                                                    );
   579→                                                }
   580→                                            }
   581→                                        }
   582→                                    }
   583→
   584→                                    // Disable validation before resuming ETL.
   585→                                    let _ = validation_controller
   586→                                        .command_tx
   587→                                        .send(Some(ValidationCommand::Disable));
   588→
   589→                                    if timed_out {
   590→                                        eprintln!(
   591→                                            "Checkpoint {} validation timed out after {}s without convergence, aborting run",
   592→                                            checkpoint_idx, MAX_WAIT.as_secs()
   593→                                        );
   594→                                        shutdown_token.cancel();
   595→                                        etl_pipeline.cancel();
   596→                                        break Some(format!(
   597→                                            "Checkpoint {checkpoint_idx} validation timed out after {}s",
   598→                                            MAX_WAIT.as_secs()
   599→                                        ));
   600→                                    }
   601→                                }
   602→                                Ok(_) => {
   603→                                    tracing::info!(
   604→                                        checkpoint_idx,
   605→                                        "No checkpoint results found, skipping validation"
   606→                                    );
   607→                                }
   608→                                Err(e) => {
   609→                                    tracing::warn!(
   610→                                        checkpoint_idx,
   611→                                        error = %e,
   612→                                        "Failed to load checkpoint results, skipping validation"
   613→                                    );
   614→                                }
   615→                            }
   616→                        }
   617→
   618→                        if let Err(e) = etl_pipeline.continue_pipeline() {
   619→                            eprintln!("Failed to continue ETL pipeline after pause: {e}");
   620→                            shutdown_token.cancel();
   621→                            break Some(format!("Failed to continue ETL pipeline: {e}"));
   622→                        }
   623→                        tracing::info!("ETL pipeline resumed");
   624→                    }
   625→                    PipelineState::Stopped(StopReason::Completed) => {
   626→                        println!("ETL pipeline completed");
   627→                        if !has_checkpoint_validation {
   628→                            // When results validation is not enabled, wait for
   629→                            // at least 1 query set iteration to complete so we
   630→                            // collect meaningful query metrics before stopping.
   631→                            const POLL_INTERVAL: Duration = Duration::from_secs(1);
   632→                            const MAX_WAIT: Duration = Duration::from_secs(300);
   633→                            let wait_start = tokio::time::Instant::now();
   634→                            loop {
   635→                                let status =
   636→                                    validation_controller.status_rx.borrow().clone();
   637→                                if status.completed_iterations() >= 1 {
   638→                                    break;
   639→                                }
   640→                                if wait_start.elapsed() >= MAX_WAIT {
   641→                                    tracing::warn!(
   642→                                        completed = status.completed_iterations(),
   643→                                        "Timed out waiting for at least 1 query set iteration after ETL completion"
   644→                                    );
   645→                                    break;
   646→                                }
   647→                                tokio::time::sleep(POLL_INTERVAL).await;
   648→                            }
   649→                        }
   650→                        println!("Stopping benchmark...");
   651→                        shutdown_token.cancel();
   652→                        break None;
   653→                    }
   654→                    PipelineState::Stopped(StopReason::Error(ref e)) => {
   655→                        eprintln!("ETL pipeline failed: {e}");
   656→                        shutdown_token.cancel();
   657→                        break Some(e.clone());
   658→                    }
   659→                    PipelineState::Stopped(StopReason::Cancelled) => {
   660→                        println!("ETL pipeline was cancelled, stopping benchmark...");
   661→                        shutdown_token.cancel();
   662→                        break None;
   663→                    }
   664→                    _ => { /* still running, keep waiting */ }
   665→                }
   666→            }
   667→            // ctrl-c: stop everything
   668→            _ = signal::ctrl_c() => {
   669→                println!("Interrupt received, stopping benchmark...");
   670→                shutdown_token.cancel();
   671→                etl_pipeline.cancel();
   672→                break None;
   673→            }
   674→        }
   675→    };
   676→
   677→    let test = match test_future.await {
   678→        Ok(test) => test,
   679→        Err(e) => {
   680→            return Err(e);
   681→        }
   682→    };
   683→
   684→    // Propagate ETL error after collecting the test result
   685→    if let Some(etl_err) = etl_error {
   686→        return Err(anyhow::anyhow!("ETL pipeline failed: {etl_err}"));
   687→    }
   688→    test.get_query_durations().statistical_set()?;
   689→
   690→    // Get all query durations for overall statistics before ending the test
   691→    let all_durations = test.get_query_durations().clone();
   692→    let all_duration_values: Vec<_> = all_durations.values().flatten().copied().collect();
   693→
   694→    let metrics: QueryMetrics<_, NoExtendedMetrics> = test.collect(TestType::Load)?;
   695→    let _ = test.end();
   696→
   697→    // Record per-query metrics for load test
   698→    for query in &metrics.metrics {
   699→        let query_name = &query.query_name;
   700→        let mut attributes = metric_attributes.clone();
   701→        attributes.push(KeyValue::new("query_name", query_name.to_string()));
   702→
   703→        let status: u64 = u64::from(match &query.query_status {
   704→            QueryStatus::Passed => true,
   705→            QueryStatus::Failed(_) => false,
   706→        });
   707→
   708→        crate::metrics::QUERY_STATUS.record(status, &attributes);
   709→        crate::metrics::MEDIAN_DURATION.record(query.median_duration_ms, &attributes);
   710→        crate::metrics::MIN_DURATION.record(query.min_duration_ms, &attributes);
   711→        crate::metrics::MAX_DURATION.record(query.max_duration_ms, &attributes);
   712→        crate::metrics::ITERATIONS.record(query.iterations.try_into()?, &attributes);
   713→        crate::metrics::P99_DURATION.record(query.percentile_99_duration_ms, &attributes);
   714→    }
   715→
   716→    // Calculate and record overall load test P99
   717→    if !all_duration_values.is_empty() {
   718→        let overall_p99 = all_duration_values.percentile(99.0)?;
   719→        crate::metrics::P99_DURATION
   720→            .record(overall_p99.as_millis().try_into()?, &metric_attributes);
   721→    }
   722→    crate::metrics::TEST_DURATION.record(
   723→        (metrics.finished_at - metrics.started_at).try_into()?,
   724→        &metric_attributes,
   725→    );
   726→
   727→    // Query throughput metrics
   728→    let total_iterations: u64 = metrics.metrics.iter().map(|q| q.iterations as u64).sum();
   729→    let test_duration_secs = (metrics.finished_at - metrics.started_at) as f64 / 1000.0;
   730→    crate::metrics::QUERIES_TOTAL.add(total_iterations, &metric_attributes);
   731→    if test_duration_secs > 0.0 {
   732→        let qps = total_iterations as f64 / test_duration_secs;
   733→        crate::metrics::QUERIES_PER_SEC.record(qps, &metric_attributes);
   734→
   735→        // Efficiency: queries/s normalized by CPU core count
   736→        let cpu_cores = std::thread::available_parallelism()
   737→            .map(|n| n.get() as f64)
   738→            .unwrap_or(1.0);
   739→        if cpu_cores > 0.0 {
   740→            crate::metrics::EFFICIENCY_QUERIES_PER_CORE.record(qps / cpu_cores, &metric_attributes);
   741→        }
   742→    }
   743→
   744→    // Stop SUT metrics scraper
   745→    sut_scraper_token.cancel();
   746→    if let Some(handle) = sut_scraper_handle
   747→        && let Ok(Some(last_sut_metrics)) = handle.await
   748→    {
   749→        println!(
   750→            "Final SUT metrics: cpu={:?}%, mem={:?}B, ingested_rows={:?}, ingested_bytes={:?}",
   751→            last_sut_metrics.resource.cpu_usage_percent,
   752→            last_sut_metrics.resource.memory_usage_bytes,
   753→            last_sut_metrics.ingestion.rows_ingested,
   754→            last_sut_metrics.ingestion.bytes_ingested,
   755→        );
   756→    }
   757→
   758→    // Stop freshness scraper and emit raw E2E latency samples.
   759→    // Percentile calculation is performed in dashboard queries.
   760→    // Only active when checkpoint validation is NOT enabled.
   761→    e2e_latency_token.cancel();
   762→    if let Some(handle) = e2e_latency_handle
   763→        && let Ok(samples_by_table) = handle.await
   764→    {
   765→        let mut total_samples = 0usize;
   766→        for (table_name, samples) in &samples_by_table {
   767→            if !samples.is_empty() {
   768→                total_samples += samples.len();
   769→                let attrs = vec![KeyValue::new("table_name", table_name.clone())];
   770→                for sample in samples {
   771→                    crate::metrics::E2E_LATENCY_MS.record(*sample, &attrs);
   772→                }
   773→            }
   774→        }
   775→        if total_samples > 0 {
   776→            println!("Recorded {total_samples} E2E latency samples");
   777→        }
   778→    }
   779→
   780→    println!("{}", vec!["-"; 30].join(""));
   781→    println!("Benchmark metrics:");
   782→    let records = metrics.build_records()?;
   783→    print_batches(&records)?;
   784→
   785→    // Shutdown streaming exporter before emitting final telemetry
   786→    if let Some(exporter) = streaming_exporter {
   787→        exporter.shutdown().await;
   788→    }
   789→
   790→    println!("Benchmark completed");
   791→
   792→    telemetry.emit().await?;
   793→
   794→    Ok(())
   795→}
   796→

